export async function liveCampusRoster(client:any,actor:SafeExitActor){
  requirePermission(actor,"VIEW_LIVE_CAMPUS_ROSTER");const today=schoolDateKey(),enrollments=await client.academicYearEnrollment.findMany({where:{status:"ACTIVE",student:{deletedAt:null,status:"Active"}},select:{academicYear:true,className:true,section:true,student:{select:{id:true,studentName:true,admissionNo:true}}},orderBy:[{className:"asc"},{section:"asc"},{student:{studentName:"asc"}}],take:10_000});const ids=enrollments.map((row:any)=>row.student.id),events=ids.length?await client.studentCampusPresenceEvent.findMany({where:{studentId:{in:ids},schoolDateKey:today},orderBy:{occurredAt:"desc"}}):[],latest=new Map<string,any>();for(const event of events)if(!latest.has(event.studentId))latest.set(event.studentId,event);return{schoolDateKey:today,generatedAt:new Date(),students:enrollments.map((row:any)=>{const event=latest.get(row.student.id),outside=event&&["EARLY_DEPARTURE","NORMAL_DISMISSAL","UNAUTHORISED_EXIT_INCIDENT"].includes(event.eventType);return{studentId:row.student.id,studentName:row.student.studentName,admissionNo:row.student.admissionNo,className:row.className,section:row.section,presence:outside?"OFF_CAMPUS":"ON_CAMPUS",lastEvent:event?{type:event.eventType,occurredAt:event.occurredAt}:null};})};
}

async function scopedRequest(client:any,actor:SafeExitActor,publicKey:string){const row=await client.studentDepartureRequest.findUnique({where:{publicKey},include:{...requestInclude,student:{select:{id:true,studentName:true,admissionNo:true,className:true,section:true,status:true,academicYear:true,guardians:{select:{guardianId:true}}}}}});if(!row)throw new SafeExitError("Student departure request was not found.",404,"NOT_FOUND");if(actor.user.role==="PARENT"&&(!actor.user.guardianId||!row.student.guardians.some((link:any)=>link.guardianId===actor.user.guardianId)))throw new SafeExitError("Student departure request was not found.",404,"NOT_FOUND");if(row.restricted&&!actor.permissions.has("VIEW_DEPARTURE_AUDIT")&&!actor.permissions.has("RECORD_UNAUTHORISED_EXIT"))throw new SafeExitError("Student departure request was not found.",404,"NOT_FOUND");return row;}
async function loadActiveStudent(client:any,id:string){const student=await client.student.findFirst({where:{id,deletedAt:null,status:"Active",academicYearEnrollments:{some:{status:"ACTIVE"}}},select:{id:true,studentName:true,admissionNo:true,className:true,section:true,status:true,academicYear:true,academicYearEnrollments:{where:{status:"ACTIVE"},select:{academicYear:true,className:true,section:true}}}});if(!student)throw new SafeExitError("An active enrolled Student was not found.",404,"STUDENT_NOT_FOUND");return student;}
