async function validatePickupForApproval(client:any,row:any,raw:any){const method=oneOf(raw.handoverMethod??row.intendedHandoverMethod,HANDOVER_METHODS,"Handover method");if(method==="STUDENT_SELF_DEPARTURE"){await currentStandingAuthorization(client,row.studentId,dateTime(raw.approvedDepartureAt??row.intendedDepartureAt,"Departure time"),true);return{method,name:row.student.studentName,relationship:"SELF",contactMasked:null,parentEvidence:"CURRENT_STANDING_GUARDIAN_AUTHORISATION",verificationReference:null};}return{method,name:text(raw.recipientName,"Pickup person name",2,120),relationship:text(raw.relationship,"Pickup relationship",2,80),contactMasked:raw.contact?maskContact(text(raw.contact,"Pickup contact",5,40)):null,parentEvidence:text(raw.parentAuthorisationEvidence,"Parent authorisation evidence",5,300),verificationReference:optional(raw.verificationReference,"Verification reference",160)};}
async function assertCurrentConsent(client:any,row:any){const evidence=await client.studentDepartureConsentEvidence.findFirst({where:{requestId:row.id,outcome:"APPROVED"},orderBy:{recordedAt:"desc"}});if(!evidence?.guardianId||!evidence.guardianLinkSnapshotHash)throw new SafeExitError("Current verifiable Guardian consent is required.",409,"CONSENT_STALE");const link=await linkedGuardian(client,row.studentId,evidence.guardianId);if(guardianLinkHash(link)!==evidence.guardianLinkSnapshotHash)throw new SafeExitError("The Guardian link changed after consent; fresh consent is required.",409,"CONSENT_STALE");if(evidence.method==="STANDING_AUTHORIZATION"){const standing=await currentStandingAuthorization(client,row.studentId,row.intendedDepartureAt,row.intendedHandoverMethod==="STUDENT_SELF_DEPARTURE");if(standing.publicKey!==evidence.standingAuthorizationKey)throw new SafeExitError("Standing Guardian authorisation was superseded or revoked.",409,"CONSENT_STALE");}return evidence;}
