async function currentCampusState(client:any,studentId:string,now=new Date()){const event=await client.studentCampusPresenceEvent.findFirst({where:{studentId,schoolDateKey:schoolDateKey(now)},orderBy:{occurredAt:"desc"}});return{event,onCampus:!event||!["EARLY_DEPARTURE","NORMAL_DISMISSAL","UNAUTHORISED_EXIT_INCIDENT"].includes(event.eventType)};}
