async function leadershipUsers(client:any,exclude:string):Promise<string[]>{const rows=await client.user.findMany({where:{id:{not:exclude},isActive:true,lifecycleStatus:"ACTIVE",iamRoleAssignments:{some:{role:{in:["SUPER_ADMIN","DIRECTOR","PRINCIPAL"]},status:"ACTIVE"}}},select:{id:true},take:50});return rows.map((row:any)=>String(row.id));}
async function authorisedWitness(client:any,userKey:any,actorId:string,leadershipOnly=false){const key=text(userKey,"Second authorised confirmation",8,80),user=await client.user.findUnique({where:{iamPublicKey:key},select:{id:true,role:true,isActive:true,lifecycleStatus:true}});if(!user||user.id===actorId||!user.isActive||user.lifecycleStatus!=="ACTIVE"||!(leadershipOnly?["SUPER_ADMIN","DIRECTOR","PRINCIPAL"].includes(user.role):["SUPER_ADMIN","DIRECTOR","PRINCIPAL","ADMIN","COMPUTER_OPERATOR"].includes(user.role)))throw new SafeExitError("A different active authorised Staff confirmation is required.",403,"WITNESS_REQUIRED");return user;}
async function appendEvent(tx:any,row:any,actor:SafeExitActor,eventType:string,previousStatus:string|null,newStatus:string|null,idempotencyKey:string,reason:string|null,metadata:any){await tx.studentDepartureEvent.create({data:{requestId:row.id,eventType,actorUserId:actor.user.id,actorRole:actor.user.role,previousStatus,newStatus,entityVersion:row.version,reason,safeMetadataJson:metadata?JSON.stringify(metadata):null,idempotencyKey}});}
function serializeRequest(row:any,actor:SafeExitActor){const gate=actor.user.role==="GATE_STAFF"||actor.permissions.has("VERIFY_GATE_PASS"),parent=actor.user.role==="PARENT",restricted=row.restricted&&!actor.permissions.has("VIEW_DEPARTURE_AUDIT")&&!actor.permissions.has("RECORD_UNAUTHORISED_EXIT");return{requestKey:row.publicKey,requestNumber:row.requestNumber,source:row.source,status:row.status,consentState:row.consentState,version:row.version,student:{id:row.student.id,name:row.student.studentName,className:row.student.className,section:row.student.section},reasonCategory:gate?undefined:row.reasonCategory,reasonDetails:gate||restricted?undefined:row.reasonDetails,intendedDepartureAt:row.intendedDepartureAt,approvedDepartureAt:row.approvedDepartureAt,approvalExpiresAt:row.approvalExpiresAt,handoverMethod:row.approvedHandoverMethod??row.intendedHandoverMethod,recipient:row.approvedRecipientName?{name:row.approvedRecipientName,relationship:row.approvedRelationship,contactMasked:row.approvedContactMasked}:null,emergencyOverride:row.emergencyOverride,checkedOutAt:row.checkedOutAt,returnedAt:row.returnedAt,events:gate||parent?row.events.filter((event:any)=>!["EMERGENCY_OVERRIDE_AUTHORISED"].includes(event.eventType)).map(publicEvent):row.events.map(publicEvent),consentEvidence:gate||parent?undefined:row.consentEvidence,gatePasses:row.gatePasses.map((pass:any)=>({publicKey:pass.publicKey,status:pass.status,expiresAt:pass.expiresAt,consumedAt:pass.consumedAt,manualCodeLastTwo:pass.manualCodeLastTwo})),handovers:row.handovers.map((handover:any)=>({method:handover.handoverMethod,recipientName:handover.recipientName,relationship:handover.relationship,contactMasked:handover.contactMasked,verifiedAt:handover.verifiedAt})),incidents:restricted?undefined:row.incidents,notifications:parent?undefined:row.notificationOutbox.map((item:any)=>({channel:item.channel,status:item.status,retryCount:item.retryCount,queuedAt:item.queuedAt,sentAt:item.sentAt,deliveredAt:item.deliveredAt,failedAt:item.failedAt,providerReferenceSafe:item.providerReferenceSafe,failureCode:item.failureCode})),fallbackTasks:parent?undefined:row.fallbackTasks};}
function publicEvent(event:any){return{type:event.eventType,previousStatus:event.previousStatus,newStatus:event.newStatus,occurredAt:event.occurredAt,reason:event.reason};}
function validateRequest(raw:any){return{studentId:text(raw.studentId,"Student",1,80),submissionKey:text(raw.submissionKey,"Submission key",8,160),source:oneOf(raw.source,SAFE_EXIT_SOURCES,"Request source"),reasonCategory:text(raw.reasonCategory,"Reason category",3,80),reasonDetails:optional(raw.reasonDetails,"Reason details",2000),intendedHandoverMethod:oneOf(raw.intendedHandoverMethod,HANDOVER_METHODS,"Intended handover method"),intendedDepartureAt:dateTime(raw.intendedDepartureAt,"Intended departure time")};}
function guardianLinkHash(link:any){return link?createHash("sha256").update(`${link.guardianId}|${link.studentId}|${link.relationshipToStudent}|${link.isPrimaryContact}`).digest("hex"):null;}
function schoolDay(value:Date){return new Date(`${schoolDateKey(value)}T00:00:00.000Z`);}
function maskContact(value:string){const digits=value.replace(/\D/g,"");return digits.length>=4?`••••••${digits.slice(-4)}`:"masked";}
function normalizeName(value:any){return String(value??"").trim().replace(/\s+/g," ").toLocaleLowerCase("en-IN");}
function requirePermission(actor:SafeExitActor,permission:CanonicalPermission){if(!actor.permissions.has(permission))throw new SafeExitError("You do not have permission for this Student safety action.",403,"PERMISSION_DENIED");}
function requireRole(actor:SafeExitActor,role:string){if(actor.user.role!==role)throw new SafeExitError("This action is unavailable in the current role context.",403,"ROLE_DENIED");}
function requireLeadership(actor:SafeExitActor){if(!["SUPER_ADMIN","DIRECTOR","PRINCIPAL"].includes(actor.user.role))throw new SafeExitError("Principal or Director authority is required.",403,"LEADERSHIP_REQUIRED");}
function conflict(){return new SafeExitError("The request changed. Refresh and retry with the current version.",409,"VERSION_CONFLICT");}
function text(value:any,label:string,min:number,max:number){const result=String(value??"").trim();if(result.length<min||result.length>max)throw new SafeExitError(`${label} must be ${min}-${max} characters.`);return result;}
function optional(value:any,label:string,max:number){const result=String(value??"").trim();return result?text(result,label,1,max):null;}
function integer(value:any,label:string,min:number,max:number){const result=Number(value);if(!Number.isInteger(result)||result<min||result>max)throw new SafeExitError(`${label} is invalid.`);return result;}
function dateTime(value:any,label:string){const result=new Date(String(value??""));if(!Number.isFinite(result.getTime()))throw new SafeExitError(`${label} is invalid.`);return result;}
function oneOf<T extends readonly string[]>(value:any,values:T,label:string):T[number]{const result=String(value??"");if(!values.includes(result))throw new SafeExitError(`${label} is invalid.`);return result as T[number];}
function arrayOfText(value:any,label:string,min:number,max:number,itemMax:number){if(!Array.isArray(value)||value.length<min||value.length>max)throw new SafeExitError(`${label} must contain ${min}-${max} entries.`);return value.map((item,index)=>text(item,`${label} ${index+1}`,1,itemMax));}
